-- =====================================================================
--  FLEMAN - fleet seed data
--
--  Generated 03 August 2026 from the CarWale image export, so every
--  car_type.image_url and car.image is a real photo of that model.
--
--  Run ONCE on a fresh database, AFTER starting the backend so Hibernate
--  has created the tables:
--      mysql -u root -p fleetmanagement < seed-data-fleet.sql
--
--  Shape
--  -----
--    15 states
--    3-5 cities per state          (58 cities, unique IATA code each)
--    1 airport hub + 2-3 city hubs per city   (203 hubs)
--    2-4 car classes per hub       (RANDOM per hub, 605 car types)
--    2-4 cars per car class        (RANDOM per class, 1813 cars)
--    2-4 add-ons per hub           (RANDOM per hub, 597 add-ons)
--    exactly 1 staff member per hub           (203 staff)
--
--  Rate card, as specified:
--    SMALL 1/2/3   COMPACT 2/3/4   INTERMEDIATE 3/4/5
--    SEDAN 4/5/6   SUV 6/7/8       (daily / weekly / monthly)
--
--  Add-on price is a random 1-5 per row.
--
--  Every seeded staff password is: Password@123
-- =====================================================================

SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM invoice_detail;
DELETE FROM invoice_header;
DELETE FROM booking_detail;
DELETE FROM booking_header;
DELETE FROM car;
DELETE FROM addon;
DELETE FROM car_type;
DELETE FROM airport;
DELETE FROM staff;
DELETE FROM hub;
DELETE FROM city;
DELETE FROM state;

ALTER TABLE car_type       AUTO_INCREMENT = 1;
ALTER TABLE addon          AUTO_INCREMENT = 1;
ALTER TABLE car            AUTO_INCREMENT = 1;
ALTER TABLE staff          AUTO_INCREMENT = 1;
ALTER TABLE airport        AUTO_INCREMENT = 1;
ALTER TABLE hub            AUTO_INCREMENT = 1;
ALTER TABLE city           AUTO_INCREMENT = 1;
ALTER TABLE state          AUTO_INCREMENT = 1;

SET FOREIGN_KEY_CHECKS = 1;


-- state: 15 rows


-- city: 58 rows


-- hub: 203 rows


-- airport: 58 rows


-- car_type: 605 rows


-- addon: 597 rows


-- car: 1813 rows


-- staff: 203 rows


